const subjects = [
  {name:'حقوق مدنی',from:1,to:20,status:'DONE'},
  {name:'آیین دادرسی مدنی',from:21,to:40,status:'IN_PROGRESS'},
  {name:'حقوق تجارت',from:41,to:60,status:'TODO'},
  {name:'اصول استنباط حقوق اسلامی',from:61,to:80,status:'TODO'},
  {name:'حقوق جزای عمومی و اختصاصی',from:81,to:100,status:'TODO'},
  {name:'آیین دادرسی کیفری',from:101,to:120,status:'TODO'}
];
const corrections = {47:{accepted_options:[1,3]},100:{accepted_options:[1,3]},106:{accepted_options:[1]}};
const out = [];
let articleIndex = 0;
for (const s of subjects) {
  if (s.status === 'DONE') continue;
  for (let start=s.from; start<=s.to; start+=4) {
    const end = Math.min(start+3,s.to);
    articleIndex++;
    const special = [];
    for (let q=start;q<=end;q++) if (corrections[q]) special.push({question:q,...corrections[q]});
    out.push({json:{...$json,article_index:articleIndex,subject:s.name,q_from:start,q_to:end,question_range:`${start}-${end}`,batch_id:`1398-C-${start}-${end}`,special_corrections:special,status:'QUEUED'}});
  }
}
return out;

const j=$json;
const questions=Array.isArray(j.questions)?j.questions:[];
const exact=questions.length===4 && questions.every(q=>q && Number.isInteger(q.number) && typeof q.text==='string' && q.text.trim() && Array.isArray(q.options) && q.options.length===4 && q.options.every(x=>typeof x==='string'&&x.trim()) && q.official_key!==undefined && Array.isArray(q.source_refs) && q.source_refs.length>0);
if(!exact){
  return [{json:{...j,source_verified:false,status:'NEEDS_SOURCE_REVIEW',publish_allowed:false,block_reason:'Exact 4 questions/options/key/source_refs not available. Connect official PDF extraction before legal analysis.'}}];
}
return [{json:{...j,source_verified:true,status:'SOURCE_VERIFIED'}}];

const j=$json;
const qs=Array.isArray(j.questions)?j.questions:[];
const qPass=qs.length===4 && qs.every(q=>q && q.analysis && q.legal_basis && q.wrong_options && q.wrong_options.length===3 && q.trap && q.example && q.dr_cheraghi_note && q.golden_point && q.gates?.source_match===true && q.gates?.key_match===true && q.gates?.legal_support===true && q.gates?.logic_consistency===true);
const seoPass=!!(j.seo?.title && j.seo?.meta_description && j.seo?.slug && j.seo?.intent && j.seo?.primary_keyword);
if(!qPass || !seoPass){
 return [{json:{...j,qc_passed:false,status:'NEEDS_REVIEW',publish_allowed:false,block_reason:!qPass?'Legal/article contract failed':'SEO contract failed'}}];
}
return [{json:{...j,qc_passed:true,status:'READY_FOR_DRAFT',publish_allowed:true,source_status:'verified',qc_status:'passed'}}];

const all=$input.all();
const counts={total:all.length,draft_ready:0,blocked:0,source_review:0,needs_review:0};
for(const i of all){const s=i.json.final_status||i.json.status; if(s==='DRAFT_READY')counts.draft_ready++; else counts.blocked++; if(s==='NEEDS_SOURCE_REVIEW')counts.source_review++; if(s==='NEEDS_REVIEW')counts.needs_review++;}
return [{json:{workflow:'Cheraghi Academy V4 Full Loop',...counts,loop_complete:true,note:'Each pending four-question article was processed as an independent n8n item. Blocked items remain fail-closed and do not prevent other batches from being evaluated.'}}];
